 52→func TestCacheReadWrite(t *testing.T) {
 53→	// Create a temporary directory for the test
 54→	tmpDir := t.TempDir()
 55→
 56→	// Create config directory structure
 57→	configDir := filepath.Join(tmpDir, globalConfigDirName)
 58→	if err := os.MkdirAll(configDir, 0o755); err != nil {
 59→		t.Fatalf("Failed to create config dir: %v", err)
 60→	}
 61→
 62→	// Test saving and loading cache directly to temp directory
 63→	originalCache := &VersionCache{
 64→		LastCheckTime: time.Now().Round(time.Second), // Round to second for JSON consistency
 65→	}
 66→
 67→	// Write cache manually to temp directory
 68→	filePath := filepath.Join(configDir, cacheFileName)
 69→	data, err := json.MarshalIndent(originalCache, "", "  ")
 70→	if err != nil {
 71→		t.Fatalf("json.MarshalIndent() error = %v", err)
 72→	}
 73→
 74→	if err := os.WriteFile(filePath, data, 0o644); err != nil {
 75→		t.Fatalf("WriteFile() error = %v", err)
 76→	}
 77→
 78→	// Load and verify
 79→
 80→	loadedData, err := os.ReadFile(filePath)
 81→	if err != nil {
 82→		t.Fatalf("ReadFile() error = %v", err)
 83→	}
 84→
 85→	var loaded VersionCache
 86→	if err := json.Unmarshal(loadedData, &loaded); err != nil {
 87→		t.Fatalf("json.Unmarshal() error = %v", err)
 88→	}
 89→
 90→	// Verify the loaded cache LastCheckTime matches (within 1 second tolerance for JSON rounding)
 91→	if loaded.LastCheckTime.Sub(originalCache.LastCheckTime).Abs() > time.Second {
 92→		t.Errorf("LastCheckTime = %v, want %v", loaded.LastCheckTime, originalCache.LastCheckTime)
 93→	}
 94→
 95→	// Verify file exists
 96→	if _, err := os.Stat(filePath); err != nil {
 97→		t.Errorf("cache file not found at %s: %v", filePath, err)
 98→	}
 99→}
